import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Grid,
  Avatar,
  Tooltip,
  Alert,
  CircularProgress
} from '@mui/material';
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  PersonAdd as RegisterIcon,
  CheckCircle as CheckInIcon,
  Schedule as ScheduleIcon,
  Group as GroupIcon,
  Person as PersonIcon
} from '@mui/icons-material';
import { scheduleApi } from '../../services/api.service';
import { TrainingSchedule, Trainer } from '../../types';

interface ScheduleListProps {
  isTrainer?: boolean;
  trainerId?: number;
}

const ScheduleList: React.FC<ScheduleListProps> = ({ isTrainer = false, trainerId }) => {
  const [schedules, setSchedules] = useState<TrainingSchedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [openDialog, setOpenDialog] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>(
    new Date().toISOString().split('T')[0]
  );

  useEffect(() => {
    fetchSchedules();
  }, [selectedDate, trainerId]);

  const fetchSchedules = async () => {
    try {
      setLoading(true);
      setError(null);

      let response;
      if (isTrainer && trainerId) {
        response = await scheduleApi.getTrainerSchedules(trainerId);
      } else {
        response = await scheduleApi.getSchedulesByDate(selectedDate);
      }

      if (response.success) {
        setSchedules((response.data as any)?.schedules || response.data || []);
      }
    } catch (err: any) {
      setError(err.message || 'Failed to fetch schedules');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'SCHEDULED':
        return 'primary';
      case 'COMPLETED':
        return 'success';
      case 'CANCELLED':
        return 'error';
      default:
        return 'default';
    }
  };

  const getTypeIcon = (type: string) => {
    return type === 'GROUP' ? <GroupIcon /> : <PersonIcon />;
  };

  const formatTime = (time: string) => {
    return new Date(`2000-01-01T${time}`).toLocaleTimeString('vi-VN', {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('vi-VN', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const getAvailableSlots = (schedule: any) => {
    const enrolled = Number(schedule.currentEnrollment ?? 0);
    const capacity = Number(schedule.maxCapacity ?? schedule.maxMembers ?? 0);
    return Math.max(0, capacity - enrolled);
  };

  const handleRegisterMember = async (scheduleId: number) => {
    // This would open a dialog to select member for registration
    console.log('Register member for schedule:', scheduleId);
  };

  const handleCheckIn = async (scheduleId: number) => {
    // This would open a dialog for member check-in
    console.log('Check in for schedule:', scheduleId);
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" height="200px">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Card>
        <CardContent>
          <Box display="flex" justifyContent="between" alignItems="center" mb={3}>
            <Typography variant="h5" gutterBottom>
              <ScheduleIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
              {isTrainer ? 'My Training Schedules' : 'Training Schedules'}
            </Typography>

            <Box display="flex" gap={2} alignItems="center">
              {!isTrainer && (
                <TextField
                  type="date"
                  label="Select Date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  size="small"
                />
              )}

              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={() => setOpenDialog(true)}
                disabled={isTrainer && !trainerId}
              >
                Create Schedule
              </Button>
            </Box>
          </Box>

          {error && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}

          {schedules.length === 0 ? (
            <Typography variant="body1" color="text.secondary" textAlign="center" py={4}>
              No schedules found for the selected {isTrainer ? 'trainer' : 'date'}.
            </Typography>
          ) : (
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Title</TableCell>
                    {!isTrainer && <TableCell>Trainer</TableCell>}
                    <TableCell>Date</TableCell>
                    <TableCell>Time</TableCell>
                    <TableCell>Type</TableCell>
                    <TableCell>Room</TableCell>
                    <TableCell>Capacity</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {schedules.map((schedule: any) => (
                    <TableRow key={schedule.id} hover>
                      <TableCell>
                        <Box>
                          <Typography variant="subtitle2" fontWeight="bold">
                            {schedule.className || schedule.title}
                          </Typography>
                          {schedule.description && (
                            <Typography variant="caption" color="text.secondary">
                              {schedule.description}
                            </Typography>
                          )}
                        </Box>
                      </TableCell>

                      {!isTrainer && (
                        <TableCell>
                          <Box display="flex" alignItems="center" gap={1}>
                            <Avatar
                              src={schedule.trainer?.user?.profile?.avatarUrl}
                              sx={{ width: 32, height: 32 }}
                            >
                              {schedule.trainer?.user?.profile?.fullName?.[0]}
                            </Avatar>
                            <Typography variant="body2">
                              {schedule.trainer?.user?.profile?.fullName}
                            </Typography>
                          </Box>
                        </TableCell>
                      )}

                      <TableCell>
                        <Typography variant="body2">
                          {formatDate(schedule.startDate || schedule.scheduleDate)}
                        </Typography>
                      </TableCell>

                      <TableCell>
                        <Typography variant="body2">
                          {formatTime(schedule.startTime)} - {formatTime(schedule.endTime)}
                        </Typography>
                      </TableCell>

                      <TableCell>
                        <Chip
                          icon={getTypeIcon(schedule.classType || schedule.scheduleType)}
                          label={schedule.classType || schedule.scheduleType}
                          variant="outlined"
                          size="small"
                        />
                      </TableCell>

                      <TableCell>
                        <Typography variant="body2">
                          {schedule.location || schedule.room || 'Not specified'}
                        </Typography>
                      </TableCell>

                      <TableCell>
                        <Box>
                          <Typography variant="body2" component="span">
                            {schedule.currentEnrollment ?? 0}
                            /{schedule.maxCapacity ?? schedule.maxMembers ?? 0}
                          </Typography>
                          <Typography variant="caption" color="text.secondary" display="block">
                            {getAvailableSlots(schedule)} available
                          </Typography>
                        </Box>
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={schedule.status}
                          color={getStatusColor(schedule.status) as any}
                          size="small"
                        />
                      </TableCell>

                      <TableCell>
                        <Box display="flex" gap={1}>
                          <Tooltip title="Edit Schedule">
                            <IconButton size="small" color="primary">
                              <EditIcon />
                            </IconButton>
                          </Tooltip>

                          {schedule.status === 'SCHEDULED' && (
                            <>
                              <Tooltip title="Register Member">
                                <IconButton
                                  size="small"
                                  color="info"
                                  onClick={() => handleRegisterMember(schedule.id)}
                                >
                                  <RegisterIcon />
                                </IconButton>
                              </Tooltip>

                              <Tooltip title="Check In">
                                <IconButton
                                  size="small"
                                  color="success"
                                  onClick={() => handleCheckIn(schedule.id)}
                                >
                                  <CheckInIcon />
                                </IconButton>
                              </Tooltip>
                            </>
                          )}

                          <Tooltip title="Cancel Schedule">
                            <IconButton
                              size="small"
                              color="error"
                              disabled={schedule.status === 'COMPLETED'}
                            >
                              <DeleteIcon />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Schedule Dialog */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>Create Training Schedule</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              <TextField
                label="Schedule Title"
                fullWidth
                required
                placeholder="e.g., Morning Yoga Class"
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                type="date"
                label="Schedule Date"
                fullWidth
                required
                InputLabelProps={{ shrink: true }}
              />
            </Grid>

            <Grid item xs={6} md={3}>
              <TextField
                type="time"
                label="Start Time"
                fullWidth
                required
                InputLabelProps={{ shrink: true }}
              />
            </Grid>

            <Grid item xs={6} md={3}>
              <TextField
                type="time"
                label="End Time"
                fullWidth
                required
                InputLabelProps={{ shrink: true }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                label="Room"
                fullWidth
                placeholder="e.g., Studio A, Main Gym"
              />
            </Grid>

            <Grid item xs={6} md={3}>
              <TextField
                type="number"
                label="Max Members"
                fullWidth
                required
                inputProps={{ min: 1, max: 50 }}
              />
            </Grid>

            <Grid item xs={6} md={3}>
              <TextField
                select
                label="Schedule Type"
                fullWidth
                required
                SelectProps={{ native: true }}
              >
                <option value="PERSONAL">Personal</option>
                <option value="GROUP">Group</option>
              </TextField>
            </Grid>

            <Grid item xs={12}>
              <TextField
                label="Description"
                fullWidth
                multiline
                rows={3}
                placeholder="Describe the training session..."
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancel</Button>
          <Button variant="contained">Create Schedule</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ScheduleList;
